import { ConvexError, v } from "convex/values";
import { internal } from "./_generated/api";
import type { Doc, Id } from "./_generated/dataModel";
import {
  internalAction,
    mutation,
      query,
        type MutationCtx,
          type QueryCtx,
          } from "./_generated/server";
          import { requireUser } from "./users";

          type LoanStatus = Doc<"loans">["status"];

          // Transitions autorisées (déclenchées par le propriétaire de l'outil)
          const TRANSITIONS: Record<LoanStatus, LoanStatus[]> = {
            pending: ["approved", "rejected"],
              approved: ["returned"],
                rejected: [],
                  returned: [],
                  };

                  /* ---------- Notification n8n ---------- */

                  // HMAC-SHA256 en hexadécimal (Web Crypto, dispo dans le runtime Convex)
                  async function hmacSha256Hex(
                    secret: string,
                      message: string,
                      ): Promise<string> {
                        const encoder = new TextEncoder();
                          const key = await crypto.subtle.importKey(
                              "raw",
                                  encoder.encode(secret),
                                      { name: "HMAC", hash: "SHA-256" },
                                          false,
                                              ["sign"],
                                                );
                                                  const signature = await crypto.subtle.sign(
                                                      "HMAC",
                                                          key,
                                                              encoder.encode(message),
                                                                );
                                                                  return Array.from(new Uint8Array(signature))
                                                                      .map((byte) => byte.toString(16).padStart(2, "0"))
                                                                          .join("");
                                                                          }

                                                                          // Construit le payload JSON et planifie l'envoi (annulé si la mutation échoue)
                                                                          async function scheduleN8nNotification(
                                                                            ctx: MutationCtx,
                                                                              event: string,
                                                                                loanId: Id<"loans">,
                                                                                ): Promise<void> {
                                                                                  const loan = await ctx.db.get(loanId);
                                                                                    if (loan === null) return;

                                                                                      const [tool, owner, borrower] = await Promise.all([
                                                                                          ctx.db.get(loan.toolId),
                                                                                              ctx.db.get(loan.ownerId),
                                                                                                  ctx.db.get(loan.borrowerId),
                                                                                                    ]);

                                                                                                      const payload = JSON.stringify({
                                                                                                          event,
                                                                                                              sentAt: Date.now(),
                                                                                                                  loan: {
                                                                                                                        id: loan._id,
                                                                                                                              status: loan.status,
                                                                                                                                    startDate: loan.startDate,
                                                                                                                                          endDate: loan.endDate,
                                                                                                                                                reminderSent: loan.reminderSent,
                                                                                                                                                    },
                                                                                                                                                        tool: tool ? { id: tool._id, name: tool.name } : null,
                                                                                                                                                            owner: owner
                                                                                                                                                                  ? { id: owner._id, name: owner.name, email: owner.email }
                                                                                                                                                                        : null,
                                                                                                                                                                            borrower: borrower
                                                                                                                                                                                  ? { id: borrower._id, name: borrower.name, email: borrower.email }
                                                                                                                                                                                        : null,
                                                                                                                                                                                          });

                                                                                                                                                                                            await ctx.scheduler.runAfter(0, internal.loans.notifyN8n, { payload });
                                                                                                                                                                                            }

                                                                                                                                                                                            // POST signé vers n8n (ne fait rien si N8N_WEBHOOK_URL n'est pas défini)
                                                                                                                                                                                            export const notifyN8n = internalAction({
                                                                                                                                                                                              args: { payload: v.string() },
                                                                                                                                                                                                handler: async (_ctx, { payload }): Promise<void> => {
                                                                                                                                                                                                    const url = process.env.N8N_WEBHOOK_URL;
                                                                                                                                                                                                        if (!url) return;

                                                                                                                                                                                                            const secret = process.env.N8N_SECRET;
                                                                                                                                                                                                                if (!secret) {
                                                                                                                                                                                                                      console.error("notifyN8n : N8N_SECRET manquant, webhook non envoyé");
                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                          const response = await fetch(url, {
                                                                                                                                                                                                                                                  method: "POST",
                                                                                                                                                                                                                                                          headers: {
                                                                                                                                                                                                                                                                    "Content-Type": "application/json",
                                                                                                                                                                                                                                                                              "x-webhook-signature": await hmacSha256Hex(secret, payload),
                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                              body: payload,
                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                          if (!response.ok) {
                                                                                                                                                                                                                                                                                                                  console.error(`notifyN8n : n8n a répondu ${response.status}`);
                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                            } catch (error) {
                                                                                                                                                                                                                                                                                                                                  console.error("notifyN8n : échec de l'envoi", error);
                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                        /* ---------- Lecture : ajoute les noms (outil, emprunteur, propriétaire) ---------- */

                                                                                                                                                                                                                                                                                                                                        async function withNames(ctx: QueryCtx, loans: Doc<"loans">[]) {
                                                                                                                                                                                                                                                                                                                                          const toolIds = Array.from(new Set(loans.map((l) => l.toolId)));
                                                                                                                                                                                                                                                                                                                                            const userIds = Array.from(
                                                                                                                                                                                                                                                                                                                                                new Set(loans.flatMap((l) => [l.borrowerId, l.ownerId])),
                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                    const toolNames = new Map<Id<"tools">, string>();
                                                                                                                                                                                                                                                                                                                                                      const userNames = new Map<Id<"users">, string>();

                                                                                                                                                                                                                                                                                                                                                        await Promise.all([
                                                                                                                                                                                                                                                                                                                                                            ...toolIds.map(async (id) => {
                                                                                                                                                                                                                                                                                                                                                                  const tool = await ctx.db.get(id);
                                                                                                                                                                                                                                                                                                                                                                        if (tool !== null) toolNames.set(id, tool.name);
                                                                                                                                                                                                                                                                                                                                                                            }),
                                                                                                                                                                                                                                                                                                                                                                                ...userIds.map(async (id) => {
                                                                                                                                                                                                                                                                                                                                                                                      const user = await ctx.db.get(id);
                                                                                                                                                                                                                                                                                                                                                                                            if (user !== null) userNames.set(id, user.name);
                                                                                                                                                                                                                                                                                                                                                                                                }),
                                                                                                                                                                                                                                                                                                                                                                                                  ]);

                                                                                                                                                                                                                                                                                                                                                                                                    return loans.map((loan) => ({
                                                                                                                                                                                                                                                                                                                                                                                                        ...loan,
                                                                                                                                                                                                                                                                                                                                                                                                            toolName: toolNames.get(loan.toolId) ?? "Outil supprimé",
                                                                                                                                                                                                                                                                                                                                                                                                                borrowerName: userNames.get(loan.borrowerId) ?? "Utilisateur inconnu",
                                                                                                                                                                                                                                                                                                                                                                                                                    ownerName: userNames.get(loan.ownerId) ?? "Utilisateur inconnu",
                                                                                                                                                                                                                                                                                                                                                                                                                      }));
                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                      /* ---------- Fonctions Convex ---------- */

                                                                                                                                                                                                                                                                                                                                                                                                                      export const requestLoan = mutation({
                                                                                                                                                                                                                                                                                                                                                                                                                        args: {
                                                                                                                                                                                                                                                                                                                                                                                                                            toolId: v.id("tools"),
                                                                                                                                                                                                                                                                                                                                                                                                                                startDate: v.number(), // timestamp en ms
                                                                                                                                                                                                                                                                                                                                                                                                                                    endDate: v.number(), // timestamp en ms
                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                        handler: async (ctx, { toolId, startDate, endDate }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                            const user = await requireUser(ctx);

                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                      !Number.isFinite(startDate) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                            !Number.isFinite(endDate) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  endDate <= startDate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new ConvexError("Dates invalides : la fin doit suivre le début");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (endDate <= Date.now()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          throw new ConvexError("La date de fin doit être dans le futur");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const tool = await ctx.db.get(toolId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (tool === null) throw new ConvexError("Outil introuvable");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!tool.isAvailable) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                throw new ConvexError("Cet outil n'est pas disponible");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tool.ownerId === user._id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              throw new ConvexError("Tu ne peux pas emprunter ton propre outil");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Pas de doublon de demande pour le même outil
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const toolLoans = await ctx.db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .query("loans")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .withIndex("by_toolId", (q) => q.eq("toolId", toolId))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .collect();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const alreadyActive = toolLoans.some(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (l) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              l.borrowerId === user._id &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (l.status === "pending" || l.status === "approved"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (alreadyActive) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    throw new ConvexError("Tu as déjà une demande en cours pour cet outil");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const loanId = await ctx.db.insert("loans", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  toolId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        borrowerId: user._id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ownerId: tool.ownerId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    startDate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          endDate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                status: "pending",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      reminderSent: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await scheduleN8nNotification(ctx, "loan.requested", loanId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return loanId;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Propriétaire de l'outil uniquement
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export const updateLoanStatus = mutation({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      args: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          loanId: v.id("loans"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              status: v.union(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v.literal("approved"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v.literal("rejected"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v.literal("returned"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        handler: async (ctx, { loanId, status }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const user = await requireUser(ctx);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const loan = await ctx.db.get(loanId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (loan === null) throw new ConvexError("Prêt introuvable");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (loan.ownerId !== user._id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              throw new ConvexError("Seul le propriétaire de l'outil peut faire ça");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!TRANSITIONS[loan.status].includes(status)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            throw new ConvexError(`Changement impossible : ${loan.status} → ${status}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const tool = await ctx.db.get(loan.toolId);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (status === "approved") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (loan.endDate <= Date.now()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      throw new ConvexError("Demande expirée (date de fin dépassée)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (tool === null || !tool.isAvailable) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          throw new ConvexError("Cet outil n'est plus disponible");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await ctx.db.patch(tool._id, { isAvailable: false });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (status === "returned" && tool !== null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await ctx.db.patch(tool._id, { isAvailable: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await ctx.db.patch(loanId, { status });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await scheduleN8nNotification(ctx, `loan.${status}`, loanId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export const getUserLoans = query({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                args: {},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  handler: async (ctx) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const user = await requireUser(ctx);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const myRequests = await ctx.db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .query("loans")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .withIndex("by_borrowerId", (q) => q.eq("borrowerId", user._id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .order("desc")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .collect();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const incomingRequests = await ctx.db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .query("loans")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .withIndex("by_ownerId", (q) => q.eq("ownerId", user._id))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .order("desc")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .collect();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const allLoans =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        user.role === "admin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? await ctx.db.query("loans").order("desc").collect()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  myRequests: await withNames(ctx, myRequests),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        incomingRequests: await withNames(ctx, incomingRequests),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              allLoans: allLoans === null ? null : await withNames(ctx, allLoans),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });